export function buildGeneratedExtractorEntries(): ExtractorEntry[] {
  const out: ExtractorEntry[] = [];
  for (const e of GENERATED_EXTRACTOR_DEFS) {
    if (HAND_OVERRIDES.has(e.ie_key)) continue;
    const Ctor = CLASS_MAP[e.className];
    if (!Ctor) continue;
    out.push({
      ie_key: e.ie_key,
      ie_name: e.ie_name,
      valid_url: e.valid_url,
      implemented: true,
      module_hint: e.module_hint,
      create: () => new Ctor(),
    });
  }
  return out;
}

